package com.raiiiden.warborn.client.shader;import java.util.*;public class ShaderRegistry{public static final ShaderRegistry INSTANCE=new ShaderRegistry();private String currentActiveShader;public Map<String,Boolean> enabled=new HashMap<>();public int calls,frames;public void processShaders(){frames++;}public static ShaderRegistry getInstance(){return INSTANCE;}public boolean setShaderEnabled(Object id,boolean value){calls++;enabled.put(id.toString(),value);if(!value&&id.equals(currentActiveShader))currentActiveShader=null;return true;}public boolean isShaderForceEnabled(String id){return Boolean.TRUE.equals(enabled.get(id));}public void active(String s){currentActiveShader=s;}public String active(){return currentActiveShader;}}
